#!/usr/bin/env node
// Black-box: one video offered as an original file (with four in-band
// subtitles) and as two HLS renditions (no subtitles) plus three extracted
// subtitle files, driven in a real Chrome. No mocks: the media is generated by
// make-fixtures.sh, the player is a built movi-player package.
//
//   node scripts/blackbox-sources/run.mjs --dist <package/dist> --media <fixtures> [--out <dir>]
//
// It reads the page the way a viewer sees it (the menus in the shadow DOM, the
// words on screen) and only reaches for the player API to tell an in-band
// track from an extracted file. Every assertion is judged on its own; the
// process exits 1 if any failed.
import { mkdir, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { chromium } from "@playwright/test";
import { startServer } from "./server.mjs";

const arg = (name, fallback) => {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : fallback;
};
const dist = resolve(arg("dist", "dist"));
const media = resolve(arg("media", "fixtures"));
const outDir = resolve(arg("out", ".blackbox-results/sources"));
// Extra attributes for the player element, so a later scenario can reuse this.
const extraSources = arg("page", "");

const TITLES = ["English", "简体中文", "Español", "Styled"];
const CUE_TOLERANCE = 0.5;

const page_html = () => `<!doctype html><meta charset="utf-8">
<body style="margin:0;background:#000">
<movi-player id="p" controls autoplay muted resumekey="bb-video" theme="dark"
  style="width:854px;height:480px">
  <source src="/media/orig.mkv" data-label="原画" data-height="480" data-default>
  <source src="/media/hls360/index.m3u8#.m3u8" data-label="360P" data-height="360">
  <source src="/media/hls240/index.m3u8#.m3u8" data-label="240P" data-height="240">
  <track kind="subtitles" src="/media/s0.srt" srclang="x0" label="[内置字幕]English" data-format="vtt" data-inband-title="English" data-inband-order="0">
  <track kind="subtitles" src="/media/s1.srt" srclang="x1" label="[内置字幕]简体中文" data-format="vtt" data-inband-title="简体中文" data-inband-order="1">
  <track kind="subtitles" src="/media/s2.srt" srclang="x2" label="[内置字幕]Español" data-format="vtt" data-inband-title="Español" data-inband-order="2">
</movi-player>
<script type="module" src="/dist/element.js"></script>
${extraSources}
</body>`;

const results = [];
const note = (name, ok, detail = "") => {
  results.push({ name, ok, detail });
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? "  — " + detail : ""}`);
};
const check = async (name, fn) => {
  try {
    const r = await fn();
    note(name, r === undefined || r === true || r.ok === true, r && r.detail ? r.detail : "");
  } catch (e) {
    note(name, false, String(e?.message ?? e).split("\n")[0]);
  }
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const server = await startServer({
  mounts: { "/media/": media, "/dist/": dist },
  pages: { "/page.html": page_html() },
});
await mkdir(outDir, { recursive: true });

const browser = await chromium.launch({
  executablePath: process.env.MOVI_CHROME_EXECUTABLE || undefined,
  headless: true,
  args: ["--autoplay-policy=no-user-gesture-required", "--no-sandbox"],
});
const context = await browser.newContext({ viewport: { width: 1000, height: 600 } });
const page = await context.newPage();
const consoleLog = [];
page.on("console", (m) => consoleLog.push(`[${m.type()}] ${m.text()}`));
page.on("pageerror", (e) => consoleLog.push(`[pageerror] ${e.message}`));

// ── page-side readers ───────────────────────────────────────────────────────
const subtitleMenu = () =>
  page.evaluate(() => {
    const r = document.querySelector("movi-player")?.shadowRoot;
    if (!r) return [];
    return [...r.querySelectorAll(".movi-subtitle-track-list .movi-subtitle-track-item")]
      .map((i) => ({
        label: (i.querySelector(".movi-subtitle-track-label")?.textContent ?? "").trim(),
        active: i.classList.contains("movi-subtitle-track-active"),
        disabled: i.classList.contains("movi-subtitle-track-disabled"),
      }))
      .filter((e) => e.label !== "Off" && e.label !== "");
  });
const sourceMenu = () =>
  page.evaluate(() => {
    const r = document.querySelector("movi-player")?.shadowRoot;
    if (!r) return [];
    return [...r.querySelectorAll(".movi-quality-list .movi-quality-item")].map((i) => ({
      label: (i.querySelector(".movi-quality-label")?.textContent ?? "").trim(),
      active: i.classList.contains("movi-quality-active"),
      src: i.dataset.src ?? "",
    }));
  });
const clickSubtitle = (label) =>
  page.evaluate((label) => {
    const r = document.querySelector("movi-player").shadowRoot;
    const item = [...r.querySelectorAll(".movi-subtitle-track-list .movi-subtitle-track-item")].find(
      (i) => (i.querySelector(".movi-subtitle-track-label")?.textContent ?? "").trim() === label,
    );
    if (!item) throw new Error(`no subtitle row ${label}`);
    item.click();
  }, label);
const clickSource = (label) =>
  page.evaluate((label) => {
    const r = document.querySelector("movi-player").shadowRoot;
    const item = [...r.querySelectorAll(".movi-quality-list .movi-quality-item")].find(
      (i) => (i.querySelector(".movi-quality-label")?.textContent ?? "").trim() === label,
    );
    if (!item) throw new Error(`no source row ${label}`);
    item.click();
  }, label);
const playerState = () =>
  page.evaluate(() => {
    const el = document.querySelector("movi-player");
    const p = el.player;
    const lang = p?.getSubtitleLangs?.().find((t) => t.active);
    const muxed = p?.trackManager?.getActiveSubtitleTrack?.();
    return {
      src: String(el.src ?? ""),
      t: el.currentTime,
      paused: el.paused,
      duration: el.duration,
      activeExternal: lang ? lang.label : null,
      activeInband: muxed ? muxed.label : null,
    };
  });
const waitFor = async (fn, ms, what) => {
  const t0 = Date.now();
  for (;;) {
    const v = await fn();
    if (v) return v;
    if (Date.now() - t0 > ms) throw new Error(`timed out waiting for ${what}`);
    await sleep(100);
  }
};
const seekAndPlay = async (t) => {
  await page.evaluate(async (t) => {
    const el = document.querySelector("movi-player");
    el.currentTime = t;
    try {
      await el.play();
    } catch {
      /* autoplay policy is off; a refusal would show as not playing below */
    }
  }, t);
};
// When does `needle` appear on screen and when does it go, in media time?
const watchCue = (needle, maxWallMs) =>
  page.evaluate(
    async ({ needle, maxWallMs }) => {
      const el = document.querySelector("movi-player");
      const read = () =>
        [...el.shadowRoot.querySelectorAll(".movi-subtitle-line")]
          .map((n) => n.textContent)
          .join(" | ");
      const t0 = performance.now();
      let on = null;
      let off = null;
      const seen = new Set();
      while (performance.now() - t0 < maxWallMs) {
        const txt = read();
        if (txt) seen.add(txt);
        const has = txt.includes(needle);
        if (has && on === null) on = el.currentTime;
        if (!has && on !== null) {
          off = el.currentTime;
          break;
        }
        await new Promise((r) => setTimeout(r, 20));
      }
      return { on, off, seen: [...seen] };
    },
    { needle, maxWallMs },
  );
const shot = (name) => page.screenshot({ path: resolve(outDir, `${name}.png`) }).catch(() => {});

const cueAt = async (label, cue, start, expectOn, expectOff) => {
  await seekAndPlay(start);
  const w = await watchCue(cue, 20_000);
  const detail = `${cue}: on ${w.on?.toFixed(2)} off ${w.off?.toFixed(2)} seen ${JSON.stringify(w.seen)}`;
  if (w.on === null) return { ok: false, detail };
  if (Math.abs(w.on - expectOn) > CUE_TOLERANCE) return { ok: false, detail };
  if (w.off !== null && Math.abs(w.off - expectOff) > CUE_TOLERANCE) return { ok: false, detail };
  if (w.seen.some((s) => /SUB-\d/.test(s) && !s.includes(cue.slice(0, 5)))) return { ok: false, detail };
  return { ok: true, detail };
};

const isHlsSrc = (s) => s.includes("hls360") || s.includes("hls240");

try {
  await page.goto(`${server.url}/page.html`);
  await waitFor(
    async () => {
      const s = await playerState().catch(() => null);
      return s && s.duration > 5 && (await subtitleMenu()).length > 0 ? s : null;
    },
    90_000,
    "the player to open the original",
  );
  await sleep(500);
  await shot("0-opened");
  const opened = await subtitleMenu();
  console.log("subtitle menu on the original:", JSON.stringify(opened));
  console.log("source menu on the original:", JSON.stringify(await sourceMenu()));

  await check("1. original: subtitle menu lists each track once (no extracted twins)", async () => {
    const labels = (await subtitleMenu()).map((e) => e.label);
    return { ok: JSON.stringify(labels) === JSON.stringify(TITLES), detail: JSON.stringify(labels) };
  });

  await check("1b. original: picking 简体中文 shows its cue at its time", async () => {
    await clickSubtitle("简体中文");
    await sleep(300);
    const s = await playerState();
    const r = await cueAt("zh", "SUB-1-A", 1, 2, 6);
    return { ok: r.ok && s.activeInband === "简体中文", detail: `${r.detail}; in-band=${s.activeInband}` };
  });

  await check("2. source menu: 原画 + 360P + 240P, no Auto", async () => {
    const labels = (await sourceMenu()).map((e) => e.label);
    return {
      ok: JSON.stringify(labels) === JSON.stringify(["原画", "360P", "240P"]),
      detail: JSON.stringify(labels),
    };
  });

  // Switch to an HLS rendition mid-playback.
  await seekAndPlay(8);
  await sleep(1500);
  const before = await playerState();
  const wall0 = Date.now();
  let switched = true;
  try {
    await clickSource("360P");
    await waitFor(
      async () => {
        const s = await playerState();
        return isHlsSrc(s.src) && !s.paused && s.t > 0 ? s : null;
      },
      90_000,
      "the 360P rendition to play",
    );
    await sleep(1000);
  } catch (e) {
    switched = false;
    note("3. switch to 360P", false, String(e.message));
  }
  const after = await playerState().catch(() => ({ t: -1, src: "", paused: true }));
  const wall = (Date.now() - wall0) / 1000;
  await shot("3-on-hls");
  console.log("after switch:", JSON.stringify(after), "wall", wall.toFixed(1));
  console.log("source menu on HLS:", JSON.stringify(await sourceMenu()));
  console.log("subtitle menu on HLS:", JSON.stringify(await subtitleMenu()));

  if (switched) {
    await check("3. switching to 360P keeps the source menu, still without Auto", async () => {
      const labels = (await sourceMenu()).map((e) => e.label);
      return {
        ok: JSON.stringify(labels) === JSON.stringify(["原画", "360P", "240P"]),
        detail: JSON.stringify(labels),
      };
    });
  }

  await check("4. position continues across the switch (+-1 s of wall time)", async () => {
    const lo = before.t - 1;
    const hi = before.t + wall + 1;
    return { ok: after.t >= lo && after.t <= hi, detail: `before ${before.t.toFixed(2)} after ${after.t.toFixed(2)} wall ${wall.toFixed(1)}` };
  });

  await check("5. on the rendition the same subtitle is still selected (an extracted file)", async () => {
    const menu = await subtitleMenu();
    const s = await playerState();
    const active = menu.filter((e) => e.active).map((e) => e.label);
    return {
      ok: JSON.stringify(active) === JSON.stringify(["简体中文"]) && s.activeExternal !== null && s.activeInband === null,
      detail: `active ${JSON.stringify(active)} external=${s.activeExternal} in-band=${s.activeInband}`,
    };
  });

  await check("5b. on the rendition the menu has the three files named for their tracks, none twice", async () => {
    const labels = (await subtitleMenu()).map((e) => e.label);
    return { ok: JSON.stringify(labels) === JSON.stringify(TITLES), detail: JSON.stringify(labels) };
  });

  await check("5c. on the rendition the cue is the right one at the right time", async () => {
    return cueAt("hls", "SUB-1-A", 1, 2, 6);
  });

  await check("6. the track no file exists for is greyed out as original-only", async () => {
    const menu = await subtitleMenu();
    const greyed = menu.filter((e) => e.disabled).map((e) => e.label);
    return { ok: JSON.stringify(greyed) === JSON.stringify(["Styled"]), detail: JSON.stringify(menu) };
  });

  // And back.
  await seekAndPlay(8);
  await sleep(1000);
  const before2 = await playerState();
  const wall1 = Date.now();
  let back = true;
  try {
    await clickSource("原画");
    await waitFor(
      async () => {
        const s = await playerState();
        return s.src.endsWith("orig.mkv") && !s.paused && s.t > 0 ? s : null;
      },
      90_000,
      "the original to play again",
    );
    await sleep(1500);
  } catch (e) {
    back = false;
    note("7. switch back to the original", false, String(e.message));
  }
  const after2 = await playerState().catch(() => ({ t: -1 }));
  const wall2 = (Date.now() - wall1) / 1000;
  await shot("7-back-on-original");

  if (back) {
    await check("7. back on the original the in-band track is used again, selection unchanged", async () => {
      const menu = await subtitleMenu();
      const s = await playerState();
      const active = menu.filter((e) => e.active).map((e) => e.label);
      const labels = menu.map((e) => e.label);
      return {
        ok:
          JSON.stringify(active) === JSON.stringify(["简体中文"]) &&
          s.activeInband === "简体中文" &&
          s.activeExternal === null &&
          JSON.stringify(labels) === JSON.stringify(TITLES),
        detail: `active ${JSON.stringify(active)} in-band=${s.activeInband} external=${s.activeExternal} labels=${JSON.stringify(labels)}`,
      };
    });
    await check("7b. back on the original the cue still shows at the right time", async () => {
      return cueAt("orig-again", "SUB-1-B", 9, 10, 14);
    });
    await check("8. position continues across the switch back (+-1 s of wall time)", async () => {
      return {
        ok: after2.t >= before2.t - 1 && after2.t <= before2.t + wall2 + 1,
        detail: `before ${before2.t.toFixed(2)} after ${after2.t.toFixed(2)} wall ${wall2.toFixed(1)}`,
      };
    });
  }
} catch (e) {
  note("harness", false, String(e?.stack ?? e).split("\n").slice(0, 3).join(" | "));
  await shot("harness-failure");
}

await writeFile(resolve(outDir, "results.json"), JSON.stringify({ results, requests: server.log.length }, null, 2));
await writeFile(resolve(outDir, "console.log"), consoleLog.join("\n"));
await browser.close();
await server.close();

const failed = results.filter((r) => !r.ok);
console.log(`\n${results.length - failed.length}/${results.length} passed`);
process.exit(failed.length ? 1 : 0);
